import { NextResponse } from "next/server";
import { z } from "zod";

const REQUEST_ID = /^[A-Za-z0-9_-]{8,64}$/u;

export class ApiRequestError extends Error {
  constructor(public code: string, public status: number, message: string) { super(message); }
}

export interface RequestContext { requestId: string; route: string; startedAt: number; }

export function requestContext(request: Request, route: string): RequestContext {
  const incoming = request.headers.get("x-request-id");
  return { requestId: incoming && REQUEST_ID.test(incoming) ? incoming : crypto.randomUUID(), route, startedAt: Date.now() };
}

export function apiError(context: RequestContext, code: string, message: string, status: number, headers?: HeadersInit, details?: unknown) {
  return NextResponse.json({ error: { code, message, requestId: context.requestId, ...(details === undefined ? {} : { details }) } }, { status, headers: { "x-request-id": context.requestId, ...headers } });
}

export function apiOk<T extends Record<string, unknown>>(context: RequestContext, body: T, status = 200, headers?: HeadersInit) {
  return NextResponse.json({ ...body, requestId: context.requestId }, { status, headers: { "x-request-id": context.requestId, ...headers } });
}

export async function parseJson<T>(request: Request, schema: z.ZodType<T>, maxBytes = 32_768): Promise<T> {
  const contentType = request.headers.get("content-type")?.split(";", 1)[0].trim().toLowerCase();
  if (contentType !== "application/json") throw new ApiRequestError("unsupported_media_type", 415, "Content-Type must be application/json.");
  const declared = Number(request.headers.get("content-length") ?? 0);
  if (Number.isFinite(declared) && declared > maxBytes) throw new ApiRequestError("payload_too_large", 413, "Request body is too large.");
  const raw = await request.text();
  if (new TextEncoder().encode(raw).byteLength > maxBytes) throw new ApiRequestError("payload_too_large", 413, "Request body is too large.");
  let value: unknown;
  try { value = JSON.parse(raw); } catch { throw new ApiRequestError("invalid_json", 400, "Request body is not valid JSON."); }
  const parsed = schema.safeParse(value);
  if (!parsed.success) throw new ApiRequestError("invalid_request", 400, "Request fields are invalid.");
  return parsed.data;
}

export function retryAfter(seconds: number): HeadersInit { return { "retry-after": String(Math.max(1, Math.ceil(seconds))) }; }

#!/usr/bin/env node

import { createHash } from "node:crypto";
import { execFileSync } from "node:child_process";
import { readFileSync } from "node:fs";

export const SOURCE_MANIFEST_PATH = "release/source-manifest.json";

function trackedBlobEntries() {
  const output = execFileSync("git", ["ls-files", "-s"], { encoding: "utf8" });
  return output
    .split("\n")
    .filter(Boolean)
    .map((line) => {
      const tab = line.indexOf("\t");
      if (tab < 0) throw new Error(`Invalid git ls-files entry: ${line}`);
      const metadata = line.slice(0, tab).trim().split(/\s+/u);
      const path = line.slice(tab + 1);
      const [, sha, stage] = metadata;
      if (!sha || stage !== "0") throw new Error(`Unsupported git index entry: ${line}`);
      return { path, sha };
    })
    .filter(({ path }) => path !== SOURCE_MANIFEST_PATH)
    .sort((a, b) => a.path.localeCompare(b.path));
}

export function computeTrackedSourceHash() {
  const hash = createHash("sha256");
  for (const { path, sha } of trackedBlobEntries()) {
    hash.update(path, "utf8");
    hash.update("\0", "utf8");
    hash.update(sha, "utf8");
    hash.update("\n", "utf8");
  }
  return hash.digest("hex");
}

export function loadSourceManifest() {
  return JSON.parse(readFileSync(SOURCE_MANIFEST_PATH, "utf8"));
}

export function checkSourceManifest() {
  const manifest = loadSourceManifest();
  const actual = computeTrackedSourceHash();
  const expected = String(manifest?.sourceHash ?? "").trim().toLowerCase();
  const releaseId = String(manifest?.releaseId ?? "").trim();

  if (!/^[0-9a-f]{64}$/u.test(expected)) {
    throw new Error("release/source-manifest.json must contain a 64-character sourceHash");
  }
  if (!releaseId) {
    throw new Error("release/source-manifest.json must contain releaseId");
  }
  if (actual !== expected) {
    throw new Error(`source manifest mismatch: expected ${expected}, actual ${actual}`);
  }

  return { releaseId, sourceHash: actual };
}

if (process.argv.includes("--check")) {
  const result = checkSourceManifest();
  console.log(`source manifest ok: ${result.releaseId} ${result.sourceHash}`);
} else if (process.argv.includes("--print")) {
  console.log(computeTrackedSourceHash());
}

#!/usr/bin/env node

import { readFileSync } from "node:fs";
import { verifyDeployment } from "./lib/release-integrity.mjs";

function argument(name) {
  const index = process.argv.indexOf(name);
  return index >= 0 ? process.argv[index + 1] : undefined;
}

function positiveInteger(value, fallback) {
  const parsed = Number.parseInt(String(value ?? ""), 10);
  return Number.isFinite(parsed) && parsed >= 0 ? parsed : fallback;
}

const manifest = JSON.parse(
  readFileSync(new URL("../release/source-manifest.json", import.meta.url), "utf8"),
);
const origin = argument("--url") || process.env.PRODUCTION_URL;
const expectedSha = argument("--expected-sha") || process.env.EXPECTED_SHA || process.env.GITHUB_SHA;
const expectedSourceHash =
  argument("--expected-source-hash") ||
  process.env.EXPECTED_SOURCE_HASH ||
  manifest.sourceHash;
const attempts = positiveInteger(argument("--attempts") || process.env.VERIFY_ATTEMPTS, 1);
const delayMs = positiveInteger(argument("--delay-ms") || process.env.VERIFY_DELAY_MS, 0);

if (!origin) {
  console.error("Production verification requires --url or PRODUCTION_URL.");
  process.exit(2);
}
if (!expectedSha) {
  console.error("Production verification requires --expected-sha, EXPECTED_SHA, or GITHUB_SHA.");
  process.exit(2);
}
if (!expectedSourceHash) {
  console.error("Production verification requires a certified source hash.");
  process.exit(2);
}

const report = await verifyDeployment({
  origin,
  expectedSha,
  expectedSourceHash,
  attempts,
  delayMs,
});
console.log(JSON.stringify(report, null, 2));

if (!report?.ok) {
  console.error("Production source-integrity/readiness verification failed.");
  process.exit(1);
}

import { createServerClient } from "@supabase/ssr";
import type { CookieOptions } from "@supabase/ssr";
import { cookies } from "next/headers";
import { NextResponse } from "next/server";
import { getPublicSupabaseConfig } from "@/lib/public-config";

export type AuthCookie = { name: string; value: string; options: CookieOptions };

export async function createClient(onSetAll?: (cookiesToSet: AuthCookie[]) => void) {
  const { url, publishableKey } = getPublicSupabaseConfig();
  const cookieStore = await cookies();
  return createServerClient(url, publishableKey, {
    cookies: {
      getAll() { return cookieStore.getAll(); },
      setAll(cookiesToSet) {
        try { cookiesToSet.forEach(({ name, value, options }) => cookieStore.set(name, value, options)); }
        catch { /* proxy.ts performs refreshes when Server Components cannot write cookies. */ }
        onSetAll?.(cookiesToSet);
      },
    },
  });
}

/**
 * Supabase auth can rotate or create session cookies while a Route Handler is
 * running. A handler's returned NextResponse is the response the browser sees,
 * so copy those mutations onto it explicitly rather than relying on the
 * request-scoped cookie store.
 */
export function applyAuthCookies(response: NextResponse, cookiesToSet: AuthCookie[]) {
  cookiesToSet.forEach(({ name, value, options }) => response.cookies.set(name, value, options));
  return response;
}

